# ---- step 2: forward model ----
import math
import re
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model for CLEVRER physics simulation.
    """
    # Handle scope - could be string or node dict
    if isinstance(scope, str):
        scope_node = node_by_title(doc, scope)
    else:
        scope_node = scope

    # Default start/horizon
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope_node)
    if horizon is None:
        horizon = 127.0

    # Physics parameters (calibrated from motion log analysis)
    DT = 0.028
    FRICTION_PER_FRAME = 0.022
    COLLISION_THRESHOLD = 0.4
    RESTITUTION = 0.5
    EXIT_BOUNDARY = 4.0
    STOP_THRESHOLD = 0.1

    # Extract motion log for initial state
    motion_records = {}
    children_list = children(doc, scope_node)
    for node in children_list:
        if node['kind'] == 'table' and 'Motion log' in node['title']:
            for _, row in table_rows(node):
                obj_match = re.match(r'(\d+)', row.get('object', ''))
                frame_str = row.get('frame', '')
                if obj_match and frame_str:
                    oid = obj_match.group(1)
                    try:
                        frame = int(float(frame_str))
                        motion_records[(oid, frame)] = {
                            'x': float(row.get('x', '0')),
                            'y': float(row.get('y', '0')),
                            'vx': float(row.get('vx', '0')),
                            'vy': float(row.get('vy', '0'))
                        }
                    except ValueError:
                        pass

    # Get initial state at start time from motion log
    int_start = int(start)
    state = {}

    # Collect all object IDs from inputs
    obj_ids = set()
    for inp in inputs:
        if inp['kind'] == 'entry':
            obj_ids.add(inp['entities'][0])

    # For each object, find latest motion record at or before start
    for oid in obj_ids:
        best_frame = None
        best_rec = None
        for (o_id, f), rec in motion_records.items():
            if o_id == oid and f <= int_start:
                if best_frame is None or f > best_frame:
                    best_frame = f
                    best_rec = rec

        if best_rec:
            sx, sy = best_rec['x'], best_rec['y']
            svx, svy = best_rec['vx'], best_rec['vy']
            frames_to_advance = int_start - best_frame
            for _ in range(frames_to_advance):
                sx += svx * DT
                sy += svy * DT
                speed = math.sqrt(svx*svx + svy*svy)
                if speed > STOP_THRESHOLD:
                    svx *= (1 - FRICTION_PER_FRAME)
                    svy *= (1 - FRICTION_PER_FRAME)
                else:
                    svx = 0
                    svy = 0
            state[oid] = {'x': sx, 'y': sy, 'vx': svx, 'vy': svy}

    outcomes = []
    collision_pairs = set()

    def apply_friction(vx, vy):
        speed = math.sqrt(vx*vx + vy*vy)
        if speed <= STOP_THRESHOLD:
            return 0.0, 0.0
        return vx * (1 - FRICTION_PER_FRAME), vy * (1 - FRICTION_PER_FRAME)

    def resolve_collision(o1, o2, s1, s2):
        dx = s2['x'] - s1['x']
        dy = s2['y'] - s1['y']
        dist = math.sqrt(dx*dx + dy*dy)
        if dist < 1e-6:
            return
        nx = dx / dist
        ny = dy / dist

        dvx = s1['vx'] - s2['vx']
        dvy = s1['vy'] - s2['vy']
        dv_norm = dvx * nx + dvy * ny

        if dv_norm > 0:
            return

        impulse = -(1 + RESTITUTION) * dv_norm / 2

        s1['vx'] -= impulse * nx
        s1['vy'] -= impulse * ny
        s2['vx'] += impulse * nx
        s2['vy'] += impulse * ny

    # Simulation loop
    t = int_start
    t_end = int(horizon)

    while t <= t_end:
        # Add objects entering at this frame
        for inp in inputs:
            if inp['kind'] == 'entry' and int(inp['time']) == t:
                oid = inp['entities'][0]
                if oid not in state:
                    fields = inp.get('fields', {})
                    state[oid] = {
                        'x': fields.get('x', 0.0),
                        'y': fields.get('y', 0.0),
                        'vx': fields.get('vx', 0.0),
                        'vy': fields.get('vy', 0.0)
                    }

        # Detect collisions
        obj_list = list(state.keys())
        for i in range(len(obj_list)):
            for j in range(i + 1, len(obj_list)):
                o1, o2 = obj_list[i], obj_list[j]
                pair = tuple(sorted([o1, o2]))
                if pair in collision_pairs:
                    continue

                dx = state[o1]['x'] - state[o2]['x']
                dy = state[o1]['y'] - state[o2]['y']
                dist = math.sqrt(dx*dx + dy*dy)

                if dist < COLLISION_THRESHOLD and dist > 1e-6:
                    nx = dx / dist
                    ny = dy / dist
                    dv_norm = ((state[o1]['vx'] - state[o2]['vx']) * nx +
                               (state[o1]['vy'] - state[o2]['vy']) * ny)

                    if dv_norm < 0:
                        resolve_collision(o1, o2, state[o1], state[o2])
                        outcomes.append({
                            'time': float(t),
                            'kind': 'collision',
                            'entities': [o1, o2],
                            'value': None,
                            'src': []
                        })
                        collision_pairs.add(pair)

        # Move objects
        for oid in list(state.keys()):
            s = state[oid]
            s['x'] += s['vx'] * DT
            s['y'] += s['vy'] * DT
            s['vx'], s['vy'] = apply_friction(s['vx'], s['vy'])

        # Check exits
        for oid in list(state.keys()):
            s = state[oid]
            if abs(s['x']) > EXIT_BOUNDARY or abs(s['y']) > EXIT_BOUNDARY:
                outcomes.append({
                    'time': float(t),
                    'kind': 'exit',
                    'entities': [oid],
                    'value': None,
                    'src': []
                })
                del state[oid]

        t += 1

    return outcomes

