import re
from collections import defaultdict

# Let's pick a video and examine its motion log and events
video_title = "Video 10017"
scope = node_by_title(doc, video_title)

# Get motion log
nodes = scope_nodes(doc, scope)
motion_node = None
events_node = None
objects_node = None
for n in nodes:
    if n.get('kind') == 'table' and ': Motion log' in n.get('title', ''):
        motion_node = n
    elif n.get('kind') == 'list' and ': Events' in n.get('title', ''):
        events_node = n
    elif n.get('kind') == 'list' and ': Objects' in n.get('title', ''):
        objects_node = n

# Parse motion log into time series per object
motion_data = defaultdict(list)
if motion_node:
    for _, row in table_rows(motion_node):
        obj_match = re.match(r"(\d+)", row['object'])
        if obj_match:
            oid = obj_match.group(1)
            motion_data[oid].append({
                'frame': float(row['frame']),
                'x': float(row['x']),
                'y': float(row['y']),
                'vx': float(row['vx']),
                'vy': float(row['vy']),
                'speed': float(row['speed'])
            })

# Sort by frame
for oid in motion_data:
    motion_data[oid].sort(key=lambda r: r['frame'])

print("Motion data for Video 10017:")
for oid, recs in motion_data.items():
    print(f"Object {oid}: {len(recs)} records")
    # Print first few and last few
    for r in recs[:2]:
        print(f"  frame {r['frame']}: pos=({r['x']:.2f}, {r['y']:.2f}), vel=({r['vx']:.2f}, {r['vy']:.2f}), speed={r['speed']:.2f}")
    if len(recs) > 4:
        print("  ...")
    for r in recs[-2:]:
        print(f"  frame {r['frame']}: pos=({r['x']:.2f}, {r['y']:.2f}), vel=({r['vx']:.2f}, {r['vy']:.2f}), speed={r['speed']:.2f}")

print("\nEvents:")
if events_node:
    for line in events_node['lines']:
        print(f"  {line}")

# Find Video 10017 and its children in doc['nodes']
