        if node['kind'] == 'list' and ': Objects' in node['title']:
            for line in node['lines']:
                m = re.match(r"Object (\d+): (.*)", line)
                if m:
                    objects[m.group(1)] = m.group(2)
        elif node['kind'] == 'list' and ': Events' in node['title']:
            for line in node['lines']:
                events.append(line)
        elif node['kind'] == 'table' and ': Motion log' in node['title']:
            for _, row in table_rows(node):
                obj_match = re.match(r"(\d+)", row['object'])
                if obj_match:
                    oid = obj_match.group(1)
                    motion_data[oid].append({
                        'frame': float(row['frame']),
                        'x': float(row['x']),
                        'y': float(row['y']),
                        'vx': float(row['vx']),
                        'vy': float(row['vy']),
                        'speed': float(row['speed'])
                    })
    for oid in motion_data:
        motion_data[oid].sort(key=lambda r: r['frame'])
    return objects, events, motion_data

