def recorded_end(doc, scope):
    nodes = scope_nodes(doc, scope)
    max_frame = None
    for node in nodes:
        title = node.get('title', '')
        if node.get('kind') == 'table' and ': Motion log' in title:
            for row_idx, row_data in table_rows(node):
                frame_str = row_data.get('frame', '')
                try:
                    frame = float(frame_str)
                    if max_frame is None or frame > max_frame:
                        max_frame = frame
                except ValueError:
                    pass
        elif node.get('kind') == 'list' and ': Events' in title:
            for line in node.get('lines', []):
                frame_match = re.match(r"Frame (\d+):", line)
                if frame_match:
                    try:
                        frame = float(frame_match.group(1))
                        if max_frame is None or frame > max_frame:
                            max_frame = frame
                    except ValueError:
                        pass
    return max_frame

def inputs(doc, scope):
    nodes = scope_nodes(doc, scope)
    events_node = None
    motion_node = None
    for node in nodes:
        title = node.get('title', '')
        if node.get('kind') == 'list' and ': Events' in title:
            events_node = node
        elif node.get('kind') == 'table' and ': Motion log' in title:
            motion_node = node

    if not events_node:
        return []

    motion_lookup = {}
    if motion_node:
        for row_idx, row_data in table_rows(motion_node):
            obj_str = row_data.get('object', '')
            obj_match = re.match(r"(\d+)", obj_str)
            frame_str = row_data.get('frame', '')
            if obj_match and frame_str:
                try:
                    obj_id = obj_match.group(1)
                    frame = float(frame_str)
                    motion_lookup[(obj_id, frame)] = (row_idx, row_data)
                except ValueError:
                    pass

    inputs_list = []
    lines = events_node.get('lines', [])

    for line_idx, line in enumerate(lines):
        frame_match = re.match(r"Frame (\d+):", line)
        if not frame_match:
            continue
        try:
            frame = float(frame_match.group(1))
        except ValueError:
            continue

        obj_match = re.search(r"Object (\d+)", line)
        if not obj_match:
            continue
        obj_id = obj_match.group(1)

        is_entry = "enters the scene" in line or "is in view when the video begins" in line

        if is_entry:
            fields = {}
            src = [[events_node['node_id'], line_idx]]

            row_idx, row_data = motion_lookup.get((obj_id, frame))
            if not row_data:
                candidates = []
                for (oid, f), (r_idx, r_data) in motion_lookup.items():
                    if oid == obj_id and f >= frame:
                        candidates.append((f, r_idx, r_data))
                if candidates:
                    candidates.sort()
                    _, row_idx, row_data = candidates[0]

            if row_data and motion_node:
                try:
                    fields['x'] = float(row_data.get('x', '0'))
                    fields['y'] = float(row_data.get('y', '0'))
                    fields['vx'] = float(row_data.get('vx', '0'))
                    fields['vy'] = float(row_data.get('vy', '0'))
                    src.append([motion_node['node_id'], row_idx])
                except ValueError:
                    pass

            inputs_list.append({
                "id": f"entry_{obj_id}",
                "time": frame,
                "kind": "entry",
                "entities": [obj_id],
                "fields": fields,
                "src": src
            })

    return inputs_list

