import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)
    if horizon is None:
        horizon = 127.0

    # Estimated parameters from data analysis
    STEP = 0.04           # position update scale per frame
    FRICTION = 0.005      # velocity decay factor per frame
    COLLISION_THRESHOLD = 0.4  # distance for collision detection
    EXIT_BOUNDARY = 3.8   # exit when outside this bound
    RESTITUTION = 0.5     # coefficient of restitution
    STOP_THRESHOLD = 0.1  # speed below which object stops

    state = {}       # obj_id -> {x, y, vx, vy}
    outcomes = []
    collision_pairs = set()  # prevent duplicate collision reporting

    def apply_friction(vx, vy):
        speed = math.sqrt(vx * vx + vy * vy)
        if speed <= STOP_THRESHOLD:
            return 0.0, 0.0
        return vx * (1.0 - FRICTION), vy * (1.0 - FRICTION)

    # Initialize state at start time from inputs
    for inp in inputs:
        if inp['kind'] != 'entry':
            continue
        obj_id = inp['entities'][0]
        entry_time = inp['time']
        fields = inp.get('fields', {})

        x = fields.get('x', 0.0)
        y = fields.get('y', 0.0)
        vx = fields.get('vx', 0.0)
        vy = fields.get('vy', 0.0)

        if entry_time <= start:
            # Advance from entry time to start
            t = int(entry_time)
            while t < int(start):
                x += vx * STEP
                y += vy * STEP
                vx, vy = apply_friction(vx, vy)
                t += 1
            state[obj_id] = {'x': x, 'y': y, 'vx': vx, 'vy': vy}

    # Main simulation loop
    t = int(start)
    t_end = int(horizon)
    while t <= t_end:
        # Add objects that enter at this frame
        for inp in inputs:
            if inp['kind'] == 'entry' and int(inp['time']) == t:
                obj_id = inp['entities'][0]
                fields = inp.get('fields', {})
                state[obj_id] = {
                    'x': fields.get('x', 0.0),
                    'y': fields.get('y', 0.0),
                    'vx': fields.get('vx', 0.0),
                    'vy': fields.get('vy', 0.0)
                }

        # Detect collisions at current positions (before update)
        obj_ids = list(state.keys())
        for i in range(len(obj_ids)):
            for j in range(i + 1, len(obj_ids)):
                o1, o2 = obj_ids[i], obj_ids[j]
                pair = tuple(sorted([o1, o2]))
                if pair in collision_pairs:
                    continue
                dx = state[o1]['x'] - state[o2]['x']
                dy = state[o1]['y'] - state[o2]['y']
                dist = math.sqrt(dx * dx + dy * dy)
                if dist < COLLISION_THRESHOLD and dist > 0.001:
                    nx = dx / dist
                    ny = dy / dist
                    # Relative velocity along normal (from o2 to o1)
                    v_rel = ((state[o1]['vx'] - state[o2]['vx']) * nx +
                             (state[o1]['vy'] - state[o2]['vy']) * ny)
                    # v_rel < 0 means approaching
                    if v_rel < 0:
                        # Elastic collision response (equal mass assumption)
                        factor = (1.0 + RESTITUTION) / 2.0
                        state[o1]['vx'] -= factor * v_rel * nx
                        state[o1]['vy'] -= factor * v_rel * ny
                        state[o2]['vx'] += factor * v_rel * nx
                        state[o2]['vy'] += factor * v_rel * ny
                        outcomes.append({
                            'time': float(t),
                            'kind': 'collision',
                            'entities': [o1, o2],
                            'value': None,
                            'src': []
                        })
                        collision_pairs.add(pair)

        # Update positions for all objects
        for obj_id in list(state.keys()):
            s = state[obj_id]
            s['x'] += s['vx'] * STEP
            s['y'] += s['vy'] * STEP
            s['vx'], s['vy'] = apply_friction(s['vx'], s['vy'])

        # Check for exits after position update
        for obj_id in list(state.keys()):
            s = state[obj_id]
            if abs(s['x']) > EXIT_BOUNDARY or abs(s['y']) > EXIT_BOUNDARY:
                outcomes.append({
                    'time': float(t),
                    'kind': 'exit',
                    'entities': [obj_id],
                    'value': None,
                    'src': []
                })
                del state[obj_id]

        t += 1

    return outcomes

